import pandas as pd
from kedro.pipeline import Pipeline, node, pipeline
from sklearn.linear_model import LinearRegression
from sklearn.model_selection import train_test_split

def nettoyer(df: pd.DataFrame) -> pd.DataFrame:
    return df.dropna().drop_duplicates()

def entrainer(df: pd.DataFrame, test_size: float, random_state: int) -> LinearRegression:
    X, y = df.drop(columns="montant"), df["montant"]
    X_tr, _, y_tr, _ = train_test_split(X, y, test_size=test_size, random_state=random_state)
    return LinearRegression().fit(X_tr, y_tr)

def create_pipeline(**kwargs) -> Pipeline:
    return pipeline([
        node(nettoyer, inputs="ventes_brutes", outputs="ventes_propres", name="nettoyage"),
        node(entrainer, inputs=["ventes_propres", "params:test_size", "params:random_state"],
             outputs="modele", name="entrainement"),
    ])

