import pandas as pd
from kedro.pipeline import node, pipeline

def nettoyer(df: pd.DataFrame) -> pd.DataFrame:
    return df.dropna()

def total_par_mois(df: pd.DataFrame) -> pd.DataFrame:
    return df.groupby(pd.to_datetime(df["date"]).dt.to_period("M"))["montant"].sum().reset_index()

def create_pipeline(**kwargs):
    return pipeline([
        node(nettoyer, "ventes_brutes", "ventes_propres"),
        node(total_par_mois, "ventes_propres", "total_mois"),
    ])
```
